use simd_paddle_ocr_rs::{ModelPreset, OcrModelSet, cpu::CpuContext, image::{ImageView, PixelFormat}};
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let directory = std::env::args_os().nth(1).ok_or("provide model directory")?;
    let raw_path = std::env::args_os().nth(2).ok_or("provide imgs_1 BGR24 pixels")?;
    let pixels = std::fs::read(raw_path)?;
    let image = ImageView::new(&pixels, 720, 1150, 0, PixelFormat::Bgr24)?;
    for preset in [ModelPreset::ChineseV6Tiny, ModelPreset::ChineseV6Small, ModelPreset::ChineseV6Medium] {
        let models = OcrModelSet::from_directory(&directory, preset, true)?;
        let mut ocr = models.builder().cpu_context(CpuContext::serial()).build()?;
        let owned = ocr.run(image, true)?.try_to_owned()?;
        assert!(!owned.text.is_empty());
        assert!(!owned.lines.is_empty());
        assert_eq!(owned.lines.len(), if matches!(preset, ModelPreset::ChineseV6Tiny) { 3 } else { 2 });
        println!("Packaged consumer {preset:?}: {} lines, {}", owned.lines.len(), owned.text);
    }
    Ok(())
}
